# Archive an actually completed public recovery attempt; no power/device/recovery actions.
[CmdletBinding()]param(
    [Parameter(Mandatory)][string]$DispatchPath,
    [Parameter(Mandatory)][ValidatePattern('\A[0-9a-f]{64}\z')][string]$DispatchSha256
)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$workspace='D:\code\ntfs2refs';$base=Join-Path $workspace '.lab\hyperv\streaming-v2-20261027';$vmId=[guid]'2401593c-4b30-472e-9b6d-c9534cbaa599'
function Need([bool]$Ok,[string]$Message){if(-not$Ok){throw $Message}}
function Hash([byte[]]$Bytes){$s=[Security.Cryptography.SHA256]::Create();try{[BitConverter]::ToString($s.ComputeHash($Bytes)).Replace('-','').ToLowerInvariant()}finally{$s.Dispose()}}
function Json([string]$Path,[string]$Pin){$m=Get-Item -LiteralPath $Path -Force;Need (-not$m.PSIsContainer -and -not($m.Attributes -band [IO.FileAttributes]::ReparsePoint) -and $m.Length -gt 0 -and $m.Length -le 1MB) 'Bounded ordinary host JSON required.';Need ((Get-FileHash -LiteralPath $Path).Hash.ToLowerInvariant() -ceq $Pin) 'Pinned dispatch/publication differs.';Get-Content -LiteralPath $Path -Raw -Encoding UTF8|ConvertFrom-Json}
$d=Json $DispatchPath $DispatchSha256
Need ($d.schema_version -eq 1 -and $d.kind -ceq 'bundle-cli-recovery-dispatch' -and [guid]$d.vm_id -eq $vmId -and $d.run_id -cmatch '\A[0-9a-f]{32}\z' -and $d.original_run_id -cmatch '\A[0-9a-f]{32}\z' -and $d.operation -cin @('Resume','Rollback') -and $d.expected_exit -eq 0 -and $d.original_printed_bundle_sha256 -cmatch '\A[0-9a-f]{64}\z') 'Actual pinned public recovery dispatch required.'
$case=Join-Path $base ('bundle-cli-20261029-'+$d.original_run_id);$attempt=Join-Path $case ('recovery-cli-'+$d.operation.ToLowerInvariant()+'-'+$d.run_id);$root=Join-Path $attempt 'closed-recovery'
Need ([IO.Path]::GetFullPath($DispatchPath) -ceq (Join-Path $attempt 'dispatch.json') -and $d.guest_stage -ceq ('C:\ntfs2refs\bundle-recovery-cli-'+$d.operation.ToLowerInvariant()+'-'+$d.run_id) -and $d.task_name -ceq ('N2R-BundleCliRecovery-'+$d.operation+'-'+$d.run_id)) 'Exact actual attempt/stage/task required.'
Need (-not(Test-Path -LiteralPath $root)) 'Archive has state; inspect without overwriting it.'
$publication=Json $d.publication_path $d.publication_sha256
Need ($publication.run_id -ceq $d.original_run_id -and $publication.actual_native_exit86_observed -eq $true -and $publication.printed_recovery_checksum -ceq $d.original_printed_bundle_sha256 -and $publication.bundle_sha256 -ceq $d.original_printed_bundle_sha256 -and $publication.printed_recovery_directory -ceq $d.original_conversion_dir -and $publication.bundle_path -ceq $d.original_bundle_path) 'Original printed recovery publication differs.'
$bundleBytes=[Convert]::FromBase64String($publication.bundle_bytes_base64);Need ($bundleBytes.Length -le 128KB -and (Hash $bundleBytes) -ceq $d.original_printed_bundle_sha256) 'Original native bundle bytes differ.';$bundle=[Text.UTF8Encoding]::new($false,$true).GetString($bundleBytes)|ConvertFrom-Json
Import-Module (Join-Path $PSScriptRoot 'Lab.psm1') -Force;$capacity=Get-LabCapacity -Configuration (Get-LabConfiguration -WorkspaceRoot $workspace)
Need ($capacity.MaximumActualBytes -eq 329374052988 -and $capacity.MinimumFreeBytes -eq 17179869184) 'Fixed capacity epoch differs.';Assert-LabCapacity -Capacity $capacity -AdditionalBytes 16MB
$session=$null;$created=$false
try{
    $session=New-PSSession -VMId $vmId -Credential (Import-Clixml (Join-Path $workspace '.lab\hyperv\win11\secrets\guest-credential.xml')) -ErrorAction Stop
    $payload=@{dispatch=$d;bundle=$bundle}|ConvertTo-Json -Depth 18 -Compress
    $text=Invoke-Command -Session $session -ArgumentList $payload -ScriptBlock {param($Payload)
        Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';$c=$Payload|ConvertFrom-Json;$d=$c.dispatch;$bundle=$c.bundle;$held=[Collections.Generic.List[IO.FileStream]]::new();$docs=[Collections.Generic.List[object]]::new();$values=@{};$pins=@{};$state=@{total=[long]0}
        function Require([bool]$Ok,[string]$Message){if(-not$Ok){throw $Message}}
        function Idle{
            $task=Get-ScheduledTask -TaskName $d.task_name;$info=Get-ScheduledTaskInfo -TaskName $d.task_name;$wrapper=Join-Path $d.guest_stage 'wrapper.ps1'
            Require ($task.State.ToString() -ceq 'Ready' -and $info.LastTaskResult -eq 0 -and $info.LastRunTime.Year -ge 2026) 'Actual public recovery task is not terminal0.'
            Require (@($task.Actions).Count -eq 1 -and $task.Actions[0].Execute -ceq "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe" -and $task.Actions[0].Arguments -ceq ('-NoProfile -NonInteractive -ExecutionPolicy Bypass -File "'+$wrapper+'"') -and $task.Principal.UserId -in @('SYSTEM','S-1-5-18') -and $task.Principal.RunLevel.ToString() -ceq 'Highest' -and (Get-FileHash -LiteralPath $wrapper).Hash.ToLowerInvariant() -ceq $d.wrapper_sha256) 'Actual registered SYSTEM wrapper differs.'
            $processes=@(Get-CimInstance Win32_Process);Require (@($processes|Where-Object {$_.Name -match '\A(?:ntfs2refs(?:-.+)?|lab-.+)\.exe\z'}).Count -eq 0 -and @(Get-ScheduledTask|Where-Object {$_.TaskName -like 'N2R-*' -and $_.State.ToString() -notin @('Ready','Disabled')}).Count -eq 0) 'Project native workers/tasks remain active or unknown.'
            ,$processes
        }
        function Collect([string]$Name,[string]$Path,[bool]$IsJson=$true){
            Require ($Path.StartsWith('C:\',[StringComparison]::OrdinalIgnoreCase) -and $Name -cmatch '\A[a-z-]+\.(json|log)\z' -and -not$values.ContainsKey($Name)) 'Only bounded closed C receipts/logs may be archived.'
            $m=Get-Item -LiteralPath $Path -Force;Require (-not$m.PSIsContainer -and -not($m.Attributes -band [IO.FileAttributes]::ReparsePoint) -and $m.Length -le 4MB -and (-not$IsJson -or $m.Length -gt 0)) 'Ordinary bounded closed file required.'
            $a=$m.Directory;while($null -ne $a){Require (-not($a.Attributes -band [IO.FileAttributes]::ReparsePoint)) 'Reparse C metadata ancestry.';$a=$a.Parent};$state.total+=$m.Length;Require ($state.total -le 4MB) 'Closed metadata/log aggregate exceeds4MiB.'
            $f=[IO.File]::Open($Path,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read);$held.Add($f);$bytes=[byte[]]::new([int]$m.Length);$at=0;while($at -lt $bytes.Length){$n=$f.Read($bytes,$at,$bytes.Length-$at);Require ($n -gt 0) 'Short closed-file read.';$at+=$n};Require ($f.Length -eq $bytes.Length) 'Closed-file length changed.'
            $sha=[Security.Cryptography.SHA256]::Create();try{$pin=[BitConverter]::ToString($sha.ComputeHash($bytes)).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()};$pins[$Name]=$pin;$values[$Name]=if($IsJson){[Text.UTF8Encoding]::new($false,$true).GetString($bytes)|ConvertFrom-Json}else{$null};$docs.Add(@{name=$Name;source=$Path;bytes=$bytes.Length;sha256=$pin;bytes_base64=[Convert]::ToBase64String($bytes)})
        }
        try{
            $processes=Idle
            # Read only the four small prerequisite receipts to establish the exact
            # process creations/exits before starting any archival collection.
            $prerequisites=@{};$prerequisitePins=@{};$prerequisiteNames=@('wrapper-worker.json','native-process.json','native-terminal.json','wrapper-result.json')
            foreach($name in $prerequisiteNames){$path=Join-Path $d.guest_stage $name;$m=Get-Item -LiteralPath $path -Force;Require (-not$m.PSIsContainer -and -not($m.Attributes -band [IO.FileAttributes]::ReparsePoint) -and $m.Length -gt 0 -and $m.Length -le 1MB) 'Small closed terminal prerequisite required.';$prerequisites[$name]=Get-Content -LiteralPath $path -Raw -Encoding UTF8|ConvertFrom-Json;$prerequisitePins[$name]=(Get-FileHash -LiteralPath $path).Hash.ToLowerInvariant()}
            $worker=$prerequisites['wrapper-worker.json'];$native=$prerequisites['native-process.json'];$terminal=$prerequisites['native-terminal.json'];$w=$prerequisites['wrapper-result.json'];$cli=@('--recover',$d.original_conversion_dir,'--recovery-sha256',$d.original_printed_bundle_sha256);if($d.operation -ceq 'Rollback'){$cli+=@('--rollback')}
            Require ($w.success -eq $true -and $w.run_id -ceq $d.run_id -and $w.original_run_id -ceq $d.original_run_id -and $w.operation -ceq $d.operation -and $w.native_exit_observed -eq $true -and $null -ne $w.native_exit -and $w.native_exit -eq 0 -and $terminal.native_exit_observed -eq $true -and $null -ne $terminal.native_exit -and $terminal.native_exit -eq 0 -and $terminal.expected_exit -eq 0 -and $w.bundle_sha256 -ceq $d.original_printed_bundle_sha256 -and $w.original_printed_pin_used -eq $true) 'Actual native0/success/original printed pin evidence differs.'
            Require ($native.binary_sha256 -ceq $d.binary_sha256 -and $native.binary -ceq (Join-Path $d.guest_stage 'ntfs2refs.exe') -and $native.process_handle_retained_before_wait -eq $true -and $native.parent_pid -eq $worker.pid -and $native.expected_exit -eq 0 -and ($native.argv -join '|') -ceq ($cli -join '|') -and $worker.run_id -ceq $d.run_id) 'Retained original process/argv evidence differs.'
            foreach($identity in @($worker,$native)){Require ($identity.pid -gt 0 -and $identity.creation_ms -gt 0) 'Actual process identity missing.';foreach($active in @($processes|Where-Object ProcessId -eq $identity.pid)){Require (([DateTimeOffset]$active.CreationDate).ToUnixTimeMilliseconds() -ne [long]$identity.creation_ms) 'Actual native/wrapper process creation is still present.'}}
            foreach($name in $prerequisiteNames){Collect $name (Join-Path $d.guest_stage $name);Require ($pins[$name] -ceq $prerequisitePins[$name]) 'Terminal prerequisite changed before collection.'}
            Require (-not(Test-Path -LiteralPath (Join-Path $d.guest_stage 'wrapper-failed.json'))) 'Original wrapper failure must not be hidden by an archive.'
            $records=[string]$w.recovery_records;Require ($records -cmatch '\AC:\\ProgramData\\ntfs2refs\\runs\\recovery-[0-9a-f]{32}\z' -and @($terminal.printed_recovery_records_paths).Count -eq 1 -and $terminal.printed_recovery_records_paths[0] -ceq $records -and $terminal.stdout.truncated -eq $false) 'Actual unique printed recovery output required.'
            foreach($name in @('stdout.log','stderr.log')){Collect $name (Join-Path $d.guest_stage $name) $false};Require ($pins['stdout.log'] -ceq $terminal.stdout.sha256 -and $pins['stderr.log'] -ceq $terminal.stderr.sha256) 'Original complete native log pins differ.'
            Collect 'typed-recovery-evidence.json' (Join-Path $d.guest_stage 'typed-recovery-evidence.json');Collect 'drive-recovery-intent.json' (Join-Path $records 'drive-recovery-intent.json')
            $roles=if($d.operation -ceq 'Resume'){@('resume','finalize')}else{@('rollback')};foreach($role in $roles){Collect ($role+'-result.json') (Join-Path (Join-Path $records $role) 'result.json')}
            $first=$d.operation.ToLowerInvariant();$last=if($d.operation -ceq 'Resume'){'finalize'}else{'rollback'};Collect 'execution.json' (Join-Path (Join-Path $records $first) 'execution.json');Collect 'completion.json' (Join-Path (Join-Path $records $last) 'completion.json');foreach($name in @('request.json','ticket.json','expectation.json')){Collect $name (Join-Path (Join-Path $records $last) $name)}
            $e=$values['typed-recovery-evidence.json'];$completion=$values['completion.json'];$execution=$values['execution.json'];$drive=$values['drive-recovery-intent.json'];$expectedAction=if($d.operation -ceq 'Resume'){'resume_then_finalize'}else{'rollback'}
            Require ($pins['request.json'] -ceq $bundle.request.sha256 -and $pins['ticket.json'] -ceq $bundle.ticket.sha256 -and $pins['expectation.json'] -ceq $bundle.expectation.sha256 -and $drive.bundle_sha256 -ceq $d.original_printed_bundle_sha256 -and $drive.bundle_path -ceq $d.original_bundle_path -and $drive.operation -ceq $expectedAction -and $e.kind -ceq 'public-bundle-cli-typed-completion-observation' -and $e.original_run_id -ceq $d.original_run_id -and $e.bundle_sha256 -ceq $d.original_printed_bundle_sha256 -and $e.recovery_records -ceq $records -and $e.completion_sha256 -ceq $pins['completion.json'] -and $w.completion_sha256 -ceq $pins['completion.json'] -and $completion.success -eq $true -and $null -eq $completion.error -and $execution.result.target_sha256 -ceq $execution.expected_target_sha256 -and $w.premount_exact_image_sha256 -ceq $execution.expected_target_sha256) 'Original bundle/input/typed completion pins differ.'
            foreach($role in $roles){$r=$values[$role+'-result.json'];Require ($r.kind -ceq 'experimental-compact-recovery' -and $r.success -eq $true -and $r.operation -ceq $role) 'Typed native role did not succeed.'}
            if($d.operation -ceq 'Resume'){Require ($w.barrier -ceq 'HND' -and $completion.rollback_closed -eq $true -and $completion.handoff.handoff_recorded -eq $true -and $completion.handoff.target_sha256 -ceq $execution.expected_target_sha256) 'Typed HND completion required.'}else{Require ($w.barrier -ceq 'ABT' -and $completion.replay_closed -eq $true -and $completion.mounted_filesystem -ceq 'NTFS' -and $completion.marker.operation -ceq 'ntfs-rollback-complete' -and $completion.marker.target_sha256 -ceq $execution.expected_target_sha256) 'Typed ABT completion required.'}
            $null=Idle
            @{success=$true;operation=$d.operation;run_id=$d.run_id;original_run_id=$d.original_run_id;native_exit_observed=$true;native_exit=0;workers_absent=$true;recovery_records=$records;bundle_sha256=$d.original_printed_bundle_sha256;barrier=$w.barrier;documents=$docs.ToArray();source_journal_packed_vhdx_image_opened=$false;power_checkpoint_attribute_actions=$false;raw_recovery_authorized=$false;utc=[DateTime]::UtcNow.ToString('o')}|ConvertTo-Json -Depth 8 -Compress
        }finally{for($i=$held.Count-1;$i -ge 0;$i--){$held[$i].Dispose()}}
    }
    $record=$text|ConvertFrom-Json;New-Item -ItemType Directory -Path $root -ErrorAction Stop|Out-Null;$created=$true;$pins=@()
    foreach($doc in $record.documents){Need ($doc.name -cmatch '\A[a-z-]+\.(json|log)\z') 'Invalid archive leaf.';$bytes=[Convert]::FromBase64String($doc.bytes_base64);Need ($bytes.Length -eq $doc.bytes -and (Hash $bytes) -ceq $doc.sha256) 'Transported original bytes differ.';$path=Join-Path $root $doc.name;$f=[IO.File]::Open($path,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$f.Write($bytes,0,$bytes.Length);$f.Flush($true)}finally{$f.Dispose()};Need ((Get-FileHash -LiteralPath $path).Hash.ToLowerInvariant() -ceq $doc.sha256) 'Host archived readback hash differs.';$pins+=@{name=$doc.name;source=$doc.source;bytes=$doc.bytes;sha256=$doc.sha256}}
    $record.documents=$pins;$record|Add-Member -NotePropertyName dispatch_sha256 -NotePropertyValue $DispatchSha256;$record|Add-Member -NotePropertyName vm_id -NotePropertyValue $vmId.ToString('D');$bytes=[Text.UTF8Encoding]::new($false).GetBytes(($record|ConvertTo-Json -Depth 10));$f=[IO.File]::Open((Join-Path $root 'receipt.json'),[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$f.Write($bytes,0,$bytes.Length);$f.Flush($true)}finally{$f.Dispose()};Get-Content -LiteralPath (Join-Path $root 'receipt.json') -Raw
}catch{if($created -and -not(Test-Path -LiteralPath (Join-Path $root 'failed.json'))){[IO.File]::WriteAllText((Join-Path $root 'failed.json'),(@{success=$false;run_id=$d.run_id;error=$_.Exception.ToString();automatic_retry=$false}|ConvertTo-Json),[Text.UTF8Encoding]::new($false))};throw}
finally{if($null -ne $session){Remove-PSSession $session}}
